typedef struct {
  int *data;
  int size;
} StreamRank;

StreamRank *streamRankCreate(void) {
  StreamRank *obj = (StreamRank *)malloc(sizeof(StreamRank));
  obj->data = (int *)malloc(sizeof(int) * 200000);
  obj->size = 0;
  return obj;
}

void streamRankTrack(StreamRank *obj, int x) {
  int i = obj->size;
  while (i > 0 && obj->data[i - 1] > x) {
    obj->data[i] = obj->data[i - 1];
    i--;
  }
  obj->data[i] = x;
  obj->size++;
}

int streamRankGetRankOfNumber(StreamRank *obj, int x) {
  int count = 0;
  for (int i = 0; i < obj->size; i++) {
    if (obj->data[i] <= x) {
      count++;
    } else {
      break;
    }
  }
  return count;
}

void streamRankFree(StreamRank *obj) {
  free(obj->data);
  free(obj);
}

class StreamRank {
  vector<int> data;

public:
  StreamRank() {}
  void track(int x) {
    data.insert(upper_bound(data.begin(), data.end(), x), x);
  }
  int getRankOfNumber(int x) {
    return upper_bound(data.begin(), data.end(), x) - data.begin();
  }
};

