class StreamRank {
  private List<Integer> data = new ArrayList<>();

  public StreamRank() {}

  public void track(int x) {
    int lo = 0, hi = data.size();
    while (lo < hi) {
      int mid = lo + (hi - lo) / 2;
      if (data.get(mid) <= x) lo = mid + 1;
      else hi = mid;
    }
    data.add(lo, x);
  }

  public int getRankOfNumber(int x) {
    int lo = 0, hi = data.size();
    while (lo < hi) {
      int mid = lo + (hi - lo) / 2;
      if (data.get(mid) <= x) lo = mid + 1;
      else hi = mid;
    }
    return lo;
  }
}

class StreamRank:
    def __init__(self):
        self.data = []

    def track(self, x: int) -> None:
        bisect.insort(self.data, x)

    def getRankOfNumber(self, x: int) -> int:
        return bisect.bisect_right(self.data, x)

impl StreamRank {
  pub fn new() -> Self {
    StreamRank { data: vec![] }
  }

  pub fn track(&mut self, x: i32) {
    let pos = self.data.partition_point(|&v| v <= x);
    self.data.insert(pos, x);
  }

  pub fn get_rank_of_number(&self, x: i32) -> i32 {
    self.data.partition_point(|&v| v <= x) as i32
  }
}

class StreamRank {
  private data: number[] = [];

  track(x: number): void {
    let lo = 0;
    let hi = this.data.length;
    while (lo < hi) {
      const mid = lo + Math.floor((hi - lo) / 2);
      if (this.data[mid] <= x) lo = mid + 1;
      else hi = mid;
    }
    this.data.splice(lo, 0, x);
  }

  getRankOfNumber(x: number): number {
    let lo = 0;
    let hi = this.data.length;
    while (lo < hi) {
      const mid = lo + Math.floor((hi - lo) / 2);
      if (this.data[mid] <= x) lo = mid + 1;
      else hi = mid;
    }
    return lo;
  }
}
